import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { ReporteService, Reporte } from '../reporte.service';

@Component({
  selector: 'app-reporte-list',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `<div class="container"><div class="header"><h2>Reportes</h2><button class="btn btn-primary" (click)="crear()">+ Generar</button></div><div *ngIf="error" class="alert">{{ error }}</div><div *ngIf="loading">Cargando...</div><table *ngIf="!loading && reportes.length" class="table"><thead><tr><th>Nombre</th><th>Tipo</th><th>Fecha</th><th>Acciones</th></tr></thead><tbody><tr *ngFor="let r of reportes"><td>{{ r.nombre_reporte }}</td><td>{{ r.tipo_reporte }}</td><td>{{ r.fecha_generacion }}</td><td><button class="btn btn-sm" (click)="ver(r.id_reporte!)">Ver</button> <button class="btn btn-sm" (click)="descargar(r.id_reporte!)">Descargar</button> <button class="btn btn-sm" (click)="eliminar(r.id_reporte!)">Eliminar</button></td></tr></tbody></table></div>`,
  styleUrls: ['./reporte-list.component.css'],
})
export class ReporteListComponent implements OnInit {
  reportes: Reporte[] = [];
  loading = true;
  error = '';

  constructor(private reporteService: ReporteService, private router: Router) {}

  ngOnInit() {
    this.cargarReportes();
  }

  cargarReportes() {
    this.loading = true;
    this.reporteService.listar().subscribe({
      next: (data) => {
        this.reportes = data;
        this.loading = false;
      },
      error: () => {
        this.error = 'Error al cargar reportes';
        this.loading = false;
      },
    });
  }

  crear() {
    this.router.navigate(['/reportes/nuevo']);
  }

  ver(id: number) {
    this.router.navigate(['/reportes', id]);
  }

  descargar(id: number) {
    this.reporteService.descargar(id).subscribe({
      error: () => (this.error = 'Error al descargar'),
    });
  }

  eliminar(id: number) {
    if (confirm('¿Eliminar?')) {
      this.reporteService.eliminar(id).subscribe({
        next: () => this.cargarReportes(),
        error: () => (this.error = 'Error'),
      });
    }
  }
}
